You can use the following code to generate a C program that reverses a string:

```c
#include <stdio.h>
#include <string.h>

int main(){
    char str[50];
    printf("Enter a text:");
    scanf("%s", str);

    char tmp;
    int len = strlen(str);

    for (int i = 0; i < len / 2; i++) {
        tmp = str[i]; 
        str[i] = str[len - i - 1];
        str[len - i - 1] = tmp; 
    }

    printf("The reversed string is: %s", str);

    return 0;
}
```

